:root {
  --ground:    #393939;
  --panel:     #434240;
  --ink:       #ffffff;
  --ink-soft:  rgba(255,255,255,0.68);
  --gold:      #c4aa84;
  --gold-deep: #a98f6a;
  --rule:      rgba(255,255,255,0.20);
  --panel-line:rgba(255,255,255,0.13);
  --focus:     #c4aa84;
  --wordmark-dark: block;
  --wordmark-light: none;

  --font-display: 'Gelasio', Georgia, serif;
  --font-body: 'Nunito', system-ui, sans-serif;
  --display-style: normal;
}
.kicker, .grouphead h2, .rail nav a, .rail .eyebrow, .fields span,
.pick-face, .send, .studio { font-family: 'Lexend', system-ui, sans-serif; }
